namespace ghidra.app.plugin.core.strings;

using docking.widgets.table.constraint;
using docking.widgets.table.constraint;
using docking.widgets.table.constrainteditor;
using docking.widgets.table.constrainteditor;
using ghidra.program.model.data;

/**
 * Tests if a string data instance has a translated value available
 */
public class HasTranslationValueColumnConstraint : StringDataInstanceColumnConstraint {

	/* @Override */
	public bool accepts(StringDataInstance value, TableFilterContext context) {
		return value.getTranslatedValue() != null && !value.getTranslatedValue().isEmpty();
	}

	/* @Override */
	public string getName() {
		return "Has Translated Value";
	}

	/* @Override */
	public ColumnConstraintEditor<StringDataInstance> getEditor(
			ColumnData<StringDataInstance> columnDataSource) {
		return new(this);
	}
}
